"""Implementation of the wildfire gas analysis module."""
from branca.element import MacroElement, Template

def combined_checks(map):
    widget = MacroElement()
    widget._template = Template('\n    {% macro script(this, kwargs) %}\n    (function(){\n      var map={{this._parent.get_name()}};\n      L.control.scale({imperial:false,metric:true,maxWidth:220,position:\'bottomleft\'}).addTo(map);\n      var root=map.getContainer();\n      var panel=document.createElement(\'div\');\n      panel.style.cssText=\'position:absolute;inset:0;pointer-events:none;z-index:450;font:10px Arial;color:black\';\n      root.appendChild(panel);\n      function label(text,x,y){\n        var el=document.createElement(\'span\');el.textContent=text;\n        el.style.cssText=\'position:absolute;background:rgba(255,255,255,.88);padding:1px 2px;transform:translate(-50%,-50%)\';\n        el.style.left=x+\'%\';el.style.top=y+\'%\';panel.appendChild(el);\n      }\n      function update(){\n        panel.innerHTML=\'\';var size=map.getSize();\n        for(var i=1;i<4;i++){\n          var lon=map.containerPointToLatLng([size.x*i/4,0]).lng;\n          var lat=map.containerPointToLatLng([0,size.y*i/4]).lat;\n          var a=Math.abs(lon).toFixed(2)+\'°\'+(lon>=0?\'E\':\'W\');\n          var c=Math.abs(lat).toFixed(2)+\'°\'+(lat>=0?\'N\':\'S\');\n          label(a,25*i,2);label(a,25*i,98);label(c,5,25*i);label(c,95,25*i);\n        }\n      }\n      map.on(\'moveend zoomend resize\',update);update();\n      var North=L.Control.extend({options:{position:\'topright\'},onAdd:function(){\n        var n=L.DomUtil.create(\'div\');\n        n.innerHTML=\'<svg width="32" height="64" viewBox="0 0 32 64" style="background:rgba(255,255,255,.9)"><text x="16" y="12" text-anchor="middle" fill="black" font-size="12" font-weight="bold">N</text><polygon points="16,18 4,56 16,43" fill="black" stroke="black"/><polygon points="16,18 28,56 16,43" fill="white" stroke="black"/></svg>\';\n        return n;\n      }});new North().addTo(map);\n      var style=document.createElement(\'style\');\n      style.textContent=\'#\'+root.id+\' .leaflet-control-scale-line{color:black;background:linear-gradient(to right,black 0%,black 20%,white 20%,white 40%,black 40%,black 60%,white 60%,white 80%,black 80%) left bottom/100% 9px no-repeat,rgba(255,255,255,.94);font-size:13px;font-weight:bold;padding-bottom:12px;border:2px solid black;text-shadow:none;}\';\n      root.appendChild(style);\n    })();\n    {% endmacro %}')
    widget.add_to(map)
